gbkT(){return"\u0646\u062d\u0648 \u0634\u0647\u0631\u064a\u0646"},
gbkP(){return"\u0623\u0643\u062b\u0631 \u0645\u0646 \u0634\u0647\u0631\u064a\u0646"},
gNQ(){return"\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0627\u0644\u0646\u0627\u062f\u064a"},
gNW(){return"\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0633\u0645"},
gNV(){return"\u062c\u064a\u0644 \u062c\u062f\u064a\u062f \u064a\u0646\u0645\u0648 \u0641\u064a \u0627\u0644\u0645\u0644\u0627\u0639\u0628. \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0645\u0648\u0633\u0645 \u0642\u062f \u064a\u0635\u0639\u062f \u0623\u062d\u062f\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0641\u0631\u064a\u0642 \u0627\u0644\u0623\u0648\u0644\u060c \u0648\u0643\u0644\u0645\u0627 \u0643\u0628\u0631\u062a \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0648\u0632\u0627\u062f\u062a \u0633\u062e\u0627\u0621 \u0627\u0644\u0645\u0646\u062d \u0627\u0631\u062a\u0641\u0639 \u0627\u062d\u062a\u0645\u0627\u0644 \u0630\u0644\u0643 \u0648\u0627\u0631\u062a\u0641\u0639 \u0633\u0642\u0641 \u0627\u0644\u062e\u0631\u064a\u062c."},
xQ(a){return"\u0627\u0644\u062a\u062e\u0631\u062c \u0627\u0644\u0642\u0627\u062f\u0645 \xb7 "+a},
gxN(){return"\u0645\u064a\u0632\u0627\u0646\u064a\u0629 \u0627\u0644\u0645\u0646\u062d"},
grl(){return"\u0645\u062d\u062f\u0648\u062f\u0629"},
grm(){return"\u0645\u062a\u0648\u0627\u0632\u0646\u0629"},
grk(){return"\u0633\u062e\u064a\u0629"},
gCQ(){return"\u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0645\u0646\u062e\u0641\u0636\u0629\u060c \u0648\u0642\u062f \u064a\u0631\u062d\u0644 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0648\u0647\u0648\u0628\u0648\u0646 \u0625\u0644\u0649 \u0623\u0646\u062f\u064a\u0629 \u0623\u062e\u0631\u0649."},
gCR(){return"\u0645\u0639\u062f\u0644 \u0627\u0644\u062a\u062e\u0631\u062c \u0648\u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0645\u062a\u0648\u0627\u0632\u0646\u0627\u0646."},
gCP(){return"\u0623\u0641\u0636\u0644 \u0627\u0644\u0645\u0648\u0627\u0647\u0628 \u062a\u062e\u062a\u0627\u0631\u0643\u060c \u0644\u0643\u0646 \u062a\u0643\u0627\u0644\u064a\u0641 \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u062a\u0631\u062a\u0641\u0639 \u0628\u0648\u0636\u0648\u062d."},
af1(a){return a+" / \u0633\u0646\u0629"},
gO_(){return"\u0627\u0644\u0645\u0646\u062d \u0627\u0644\u0633\u0646\u0648\u064a\u0629"},
gNO(){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0645\u064a\u0632\u0627\u0646\u064a\u0629 \u0627\u0644\u0645\u0646\u062d"},
gxP(){return"\u0646\u0627\u0634\u0626\u0648\u0646 \u0623\u0643\u062b\u0631"},
gxO(){return"\u0633\u0642\u0641 \u0623\u0639\u0644\u0649"},
gNR(){return"\u062a\u062e\u0631\u062c \u0623\u0643\u062b\u0631 \u062a\u0643\u0631\u0627\u0631\u064b\u0627"},
gNP(){return"\u062a\u0643\u0628\u0631 \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0645\u0631\u062d\u0644\u0629 \u0648\u0627\u062d\u062f\u0629: \u0646\u0627\u0634\u0626\u0648\u0646 \u0623\u0643\u062b\u0631\u060c \u0648\u0633\u0642\u0641 \u0623\u0639\u0644\u0649\u060c \u0648\u062a\u062e\u0631\u062c \u0623\u0643\u062b\u0631 \u062a\u0643\u0631\u0627\u0631\u064b\u0627. \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0627\u0644\u0623\u062b\u0631 \u062d\u062a\u0649 \u064a\u0646\u062a\u0647\u064a \u0627\u0644\u0628\u0646\u0627\u0621."},
gNS(){return"\u062a\u064f\u062c\u062f\u064e\u0651\u062f \u0627\u0644\u0645\u0644\u0627\u0639\u0628 \u0648\u0627\u0644\u0645\u0628\u0627\u0646\u064a\u060c \u0648\u062a\u0639\u0645\u0644 \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0628\u0643\u0627\u0645\u0644 \u0643\u0641\u0627\u0621\u062a\u0647\u0627 \u0645\u0646 \u062c\u062f\u064a\u062f."},
NT(a){return"\u0627\u0644\u0631\u0627\u0641\u0639\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0648\u0642\u0639. \u064a\u062a\u0628\u0642\u0649 "+a+" \u0639\u0644\u0649 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u060c \u0648\u062a\u0633\u062a\u0645\u0631 \u0627\u0644\u0645\u0646\u062d \u0648\u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0643\u0627\u0644\u0645\u0639\u062a\u0627\u062f \u062e\u0644\u0627\u0644 \u0630\u0644\u0643."},
gNU(){return"\u0627\u0644\u0631\u0627\u0641\u0639\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0648\u0642\u0639. \u062a\u0633\u062a\u0645\u0631 \u0627\u0644\u0645\u0646\u062d \u0648\u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0643\u0627\u0644\u0645\u0639\u062a\u0627\u062f \u062d\u062a\u0649 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d."},
gCT(){return"\u0645\u0646 \u0623\u0641\u0636\u0644 \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0627\u062a \u0641\u064a \u0627\u0644\u0628\u0644\u0627\u062f"},
gCS(){return"\u0644\u0645 \u062a\u0639\u062f \u0647\u0646\u0627\u0643 \u0645\u0631\u062d\u0644\u0629 \u0644\u0644\u062a\u0637\u0648\u064a\u0631. \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0627\u0644\u0622\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u0646\u062d \u0628\u0630\u0643\u0627\u0621 \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u064a\u062f\u0629."},
gNX(){return"\u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0628\u062d\u0627\u0644\u0629 \u062c\u064a\u062f\u0629\u060c \u0648\u0644\u0627 \u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0625\u0635\u0644\u0627\u062d."},
gNZ(){return"\u0628\u062f\u0623\u062a \u0627\u0644\u0645\u0644\u0627\u0639\u0628 \u062a\u062a\u0622\u0643\u0644\u060c \u0648\u0645\u0648\u0639\u062f \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u064a\u0642\u062a\u0631\u0628."},
gNY(){return"\u062a\u0622\u0643\u0644\u062a \u0627\u0644\u0645\u0644\u0627\u0639\u0628 \u0628\u0634\u062f\u0629\u060c \u0648\u0627\u0644\u0646\u0627\u0634\u0626\u0648\u0646 \u064a\u062a\u0623\u062b\u0631\u0648\u0646 \u0628\u0630\u0644\u0643."},
gxU(){return"\u0645\u0646\u0634\u0623\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0628"},
